"""
    Scales a cube coord.
    :param c: A cube coord x, z, y.
    :param s: The amount to scale the cube coord.
    :return: The scaled cube coord.
    """
def scale(c: Any, s: Any) -> object {
    (cx, cz, cy) = c;
    return ((s * cx), (s * cz), (s * cy));
}

