"""returns the text with "toRemove" stripped from the start if it matches
>>> removeFromStart('abcd', 'a')
'bcd'
>>> removeFromStart('abcd', 'not')
'abcd'

working of ignoreCase:

>>> removeFromStart('ABCD', 'a')
'ABCD'
>>> removeFromStart('ABCD', 'ab', ignoreCase=1)
'CD'
>>> removeFromStart('abcd', 'ABC', ignoreCase=1)
'd'

    """
def removeFromStart(text: Any, toRemove: Any, ignoreCase: Any = None) -> object {
    if ignoreCase {
        text2 = text.lower();
        toRemove = toRemove.lower();
    } else {
        text2 = text;
    }
    if text2.startswith(toRemove) {
        return text[len(toRemove):];
    } else {
        return text;
    }
}

"""
        Sort transactions by amount of dollars.
    """
def _sort_by_amount(transactions: list) -> list {
    sorted_transactions = sorted(
        transactions,
        key=lambda (transaction: Any) { transaction["amount"]; },
        reverse=True
    );
    return sorted_transactions;
}

""" ersetzt alle Vorkommen von '<a href="xxxxxxxx" ... >yyyy</a>' durch '(xxxxxxxx : yyyy)' """
def links_as_text(code: Any) -> object {
    def link_as_text(code: Any) -> object {
        ret = code;
        i = code.rfind('<a href="');
        if (i > -1) {
            j = code.find('"', (i + 9));
            k = code.find('>', j);
            l = code.find('<', k);
            ret = (
                code[:i]
                + '('
                + code[(i + 9):j]
                + ' : '
                + code[(k + 1):l]
                + ')'
                + code[(l + 4):]
            );
        }
        return (i, ret);
    }
    i = 1;
    ret = code;
    while (i > -1) {
        (i, ret) = link_as_text(ret);
    }
    return ret;
}
